package server.bots;
import client.Character;import server.life.Monster;import scripting.event.EventInstanceManager;import java.awt.Point;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class BotPinkBeanStancesTest {
 @Test void rexApproachDoesNotWalkAcrossHisBodyOrUseThePlatformThatDropsIntoHim(){
  var b=mock(Character.class);var ev=mock(EventInstanceManager.class);var rex=mock(Monster.class);when(b.getEventInstance()).thenReturn(ev);when(b.getJob()).thenReturn(client.Job.DARKKNIGHT);when(rex.getId()).thenReturn(8820004);
  try(var pink=mockStatic(BotPinkBeanRun.class)){pink.when(()->BotPinkBeanRun.inInstance(b)).thenReturn(true);when(ev.getIntProperty("stage")).thenReturn(2);assertTrue(BotPinkBeanStances.allows(b,new Point(450,-42),rex));assertFalse(BotPinkBeanStances.allows(b,new Point(900,-42),rex));assertFalse(BotPinkBeanStances.allows(b,new Point(540,-277),rex));when(ev.getIntProperty("stage")).thenReturn(4);assertTrue(BotPinkBeanStances.allows(b,new Point(900,-42),rex));assertFalse(BotPinkBeanStances.allows(b,new Point(450,-42),rex));}
 }
 @Test void huginIsApproachedAtTheOuterLowerPlatformInsteadOfJumpingAcrossHisBody(){var b=mock(Character.class);var ev=mock(EventInstanceManager.class);var bird=mock(Monster.class);when(b.getEventInstance()).thenReturn(ev);when(bird.getId()).thenReturn(8820005);try(var pink=mockStatic(BotPinkBeanRun.class)){pink.when(()->BotPinkBeanRun.inInstance(b)).thenReturn(true);assertTrue(BotPinkBeanStances.allows(b,new Point(-550,-99),bird));assertFalse(BotPinkBeanStances.allows(b,new Point(-433,-150),bird));assertFalse(BotPinkBeanStances.allows(b,new Point(-174,-206),bird));}}
 @Test void rangedSagePositionHasVerticalReachAndRecoilRoomOnTheTopPlatform(){var b=mock(Character.class);var ev=mock(EventInstanceManager.class);var sage=mock(Monster.class);when(b.getEventInstance()).thenReturn(ev);when(b.getJob()).thenReturn(client.Job.NIGHTLORD);when(sage.getId()).thenReturn(8820004);try(var pink=mockStatic(BotPinkBeanRun.class)){pink.when(()->BotPinkBeanRun.inInstance(b)).thenReturn(true);assertTrue(BotPinkBeanStances.allows(b,new Point(350,-456),sage));assertFalse(BotPinkBeanStances.allows(b,new Point(900,-42),sage));assertFalse(BotPinkBeanStances.allows(b,new Point(540,-258),sage));}}
}
